CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `projeto`.`teto_vidro` AS with `presenca_senioridade` as (select `s`.`ordem_hierarquica` AS `ordem_hierarquica`,`s`.`senioridade` AS `senioridade`,`s`.`classificacao_lideranca` AS `classificacao_lideranca`,count(0) AS `total_profissionais`,sum((case when (`m`.`genero` = 'Feminino') then 1 else 0 end)) AS `total_mulheres`,sum((case when (`m`.`genero` = 'Masculino') then 1 else 0 end)) AS `total_homens` from (`projeto`.`fato_mercado_salarios_tech` `m` join `projeto`.`dim_senioridade` `s` on((`m`.`senioridade` = `s`.`senioridade`))) group by `s`.`ordem_hierarquica`,`s`.`senioridade`,`s`.`classificacao_lideranca`) select `presenca_senioridade`.`ordem_hierarquica` AS `ordem_hierarquica`,`presenca_senioridade`.`senioridade` AS `senioridade`,`presenca_senioridade`.`classificacao_lideranca` AS `classificacao_lideranca`,`presenca_senioridade`.`total_profissionais` AS `total_profissionais`,`presenca_senioridade`.`total_mulheres` AS `total_mulheres`,`presenca_senioridade`.`total_homens` AS `total_homens`,round(((`presenca_senioridade`.`total_mulheres` * 100.0) / `presenca_senioridade`.`total_profissionais`),2) AS `pct_mulheres`,round(((`presenca_senioridade`.`total_homens` * 100.0) / `presenca_senioridade`.`total_profissionais`),2) AS `pct_homens` from `presenca_senioridade` order by `presenca_senioridade`.`ordem_hierarquica`